FatturaElettronicaBody.DatiBeniServizi:
{%- for line in lines %}

  {{ line.idx }}
  {{ line.description }}
  {{ line.qty }}
  {{ line.uom }}
  {{ line.unit_price }}
  {{ line.total_price }}
  {{ line.tax_rate }}
  {%- if line.nature %}
  {{ line.nature }}
  {%- endif %}

{%- endfor %}
{%- for summary in summaries %}

  {{ summary.rate }}
  {%- if summary.nature %}
  {{ summary.nature }}
  {%- endif %}
  {{ summary.taxable_amount }}
  {{ summary.tax_amount }}
  {%- if summary.law %}
  {{ summary.law }}
  {%- endif %}

{%- endfor %}
